class UnionFind:            # Quick Find implementation
    def __init__(self, n):  
        self.root = list(range(n))

    def find(self, x):
        return self.root[x]

    def union(self, x, y):
        rootx = self.root[x]
        rooty = self.root[y]
        if rootx != rooty:
            for i, root_i in enumerate(self.root):
                if root_i == rootx:
                    self.root[i] = rooty     # replace all 'rootx' with 'rooty'

class Solution:             # UnionFind; TC: O(N^2) as 'union' loop only if rootx != rooty, SC: O(N);
    def findCircleNum(self, isConnected: List[List[int]]) -> int:
        n = len(isConnected)
        uf = UnionFind(n)
        for x in range(n):
            for y in range(n):
                if isConnected[x][y]:
                    uf.union(x, y)
        return len(set(uf.root))             # Quick Union method will not work here; need to use Quick find method

