def shortest_path(graph: Dict[str, List[Tuple[str, int]]], start: str, end: str) -> List[str]:
    # Check if the start and end warehouses exist in the graph
    if start not in graph or end not in graph:
        raise ValueError("Invalid start or end warehouse")

    # Priority queue for Dijkstra's algorithm
    priority_queue = [(0, start, [])]  # (distance, current_node, path)
    visited = set()

    while priority_queue:
        current_distance, current_node, path = heapq.heappop(priority_queue)

        if current_node in visited:
            continue

        visited.add(current_node)
        new_path = path + [current_node]

        if current_node == end:
            return new_path

        for neighbor, weight in graph.get(current_node, []):
            if neighbor not in visited:
                heapq.heappush(priority_queue, (current_distance + weight, neighbor, new_path))

    # If there's no path to the end warehouse
    return []

