def all_pairs_shortest_path(adjacency_matrix: List[List[float]]) -> List[List[float]]:
    """
    Uses the Floyd-Warshall algorithm to compute the shortest paths between all pairs of nodes.
    """
    n = len(adjacency_matrix)
    # Initialize distance matrix with the given adjacency matrix
    dist = [row[:] for row in adjacency_matrix]

    # Applying Floyd-Warshall algorithm
    for k in range(n):
        for i in range(n):
            for j in range(n):
                if dist[i][k] + dist[k][j] < dist[i][j]:
                    dist[i][j] = dist[i][k] + dist[k][j]

    return dist

