def priority_queue_operations(operations):
    min_heap = []
    result = []

    for operation in operations:
        if operation.startswith("insert"):
            _, x = operation.split()
            heapq.heappush(min_heap, int(x))
        elif operation == "extract_min":
            if min_heap:
