def find_duplicates(s):
    """
    Returns a dictionary of duplicate characters and their counts in the input string.
    """
    char_count = {}
    duplicates = {}

    for char in s:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    for char, count in char_count.items():
        if count > 1:
            duplicates[char] = count

