def single_number3(nums: List[int]) -> List[int]:
    # Step 1: XOR all numbers to get the XOR of the two unique numbers
    xor = 0
    for num in nums:
        xor ^= num

    # Step 2: Find the right-most set bit of xor
    rightmost_set_bit = xor & -xor

    # Step 3: Divide numbers into two groups and XOR each group
    num1, num2 = 0, 0
    for num in nums:
        if num & rightmost_set_bit:
            num1 ^= num
        else:
            num2 ^= num

    return [num1, num2]

def two_sum(array, target):
    """
    Finds two indices of elements in `array` that add up to `target`.

    Args:
    array (List[int]): The list of integers.
    target (int): The target sum.

    Returns:
    Tuple[int, int]: A tuple containing the indices of the two elements that add up to `target`.
    """
    num_to_index = {}

    for index, num in enumerate(array):
        complement = target - num
        if complement in num_to_index:
            return (num_to_index[complement], index)
        num_to_index[num] = index

    return None  # This will never be reached due to constraint guarantees.

