    # Step 1: Initialize distances from source to all other nodes as infinity
    # and distance to source itself as 0.
    distances = {node: float('inf') for node in graph}
    distances[source] = 0

    # Step 2: Relax all edges |V| - 1 times.
    for i in range(len(graph) - 1):
        for node in graph:
            for neighbor in graph[node]:
                if distances[node] + graph[node][neighbor] < distances[neighbor]:
                    distances[neighbor] = distances[node] + graph[node][neighbor]

    # Step 3: Check for negative-weight cycles.
    for node in graph:
        for neighbor in graph[node]:
            if distances[node] + graph[node][neighbor] < distances[neighbor]:
