def is_strictly_increasing(lst):
    """
    Returns True if the list 'lst' is strictly increasing, False otherwise.
    """
    # An empty list or a list with a single element is considered strictly increasing
    if len(lst) <= 1:
        return True

    # Iterate over the list and check if each element is strictly
    # greater than the previous one
    for i in range(1, len(lst)):
        if lst[i] <= lst[i - 1]:
            return False
    return True

def find_duplicates(lst: list) -> dict:
    """
    Returns a dictionary where each key is a duplicate element from the list 
    and the value is a list of indices at which that element occurs.
    """
    element_indices = {}
    duplicates = {}

    for index, element in enumerate(lst):
        if element in element_indices:
            element_indices[element].append(index)
            duplicates[element] = element_indices[element]
        else:
            element_indices[element] = [index]

    return {k: v for k, v in duplicates.items() if len(v) > 1}

